CREATE TYPE "OrderRefundStatus" AS ENUM ('NONE', 'PARTIAL', 'FULL');
CREATE TYPE "RefundRequestStatus" AS ENUM ('REQUESTED', 'UNDER_REVIEW', 'APPROVED', 'REFUND_PENDING', 'REFUNDED', 'REJECTED', 'FAILED', 'CANCELLED');
CREATE TYPE "RefundStatus" AS ENUM ('CREATED', 'PENDING', 'UNKNOWN', 'REFUNDED', 'FAILED');
CREATE TYPE "ReturnRequestStatus" AS ENUM ('REQUESTED', 'APPROVED', 'REJECTED', 'AWAITING_ITEM', 'ITEM_RECEIVED', 'INSPECTING', 'COMPLETED', 'CANCELLED');
CREATE TYPE "ReturnReasonCode" AS ENUM ('DAMAGED', 'WRONG_ITEM', 'DEFECTIVE', 'NOT_AS_DESCRIBED', 'CHANGED_MIND', 'OTHER');
CREATE TYPE "ReturnResolution" AS ENUM ('REFUND', 'REPLACEMENT', 'NO_ACTION');
CREATE TYPE "WarrantyClaimStatus" AS ENUM ('SUBMITTED', 'UNDER_REVIEW', 'APPROVED', 'REJECTED', 'IN_SERVICE', 'RESOLVED');
CREATE TYPE "WarrantyResolution" AS ENUM ('REPAIR', 'REPLACEMENT', 'REFUND', 'NO_FAULT_FOUND');
CREATE TYPE "CommissionRecordStatus" AS ENUM ('EARNED');
CREATE TYPE "SupplierLedgerEntryType" AS ENUM ('SUPPLIER_EARNING', 'REFUND_DEBIT', 'MANUAL_ADJUSTMENT', 'SETTLEMENT_DEBIT');
CREATE TYPE "SupplierSettlementStatus" AS ENUM ('DRAFT', 'APPROVED', 'PAID', 'CANCELLED');

ALTER TABLE "Order" ADD COLUMN "refundStatus" "OrderRefundStatus" NOT NULL DEFAULT 'NONE';
ALTER TABLE "SupplierListing" ADD COLUMN "warrantyDays" INTEGER;
ALTER TABLE "OrderItem" ADD COLUMN "warrantyDaysSnapshot" INTEGER;
ALTER TABLE "SupplierListing" ADD CONSTRAINT "SupplierListing_warrantyDays_nonnegative" CHECK ("warrantyDays" IS NULL OR "warrantyDays" >= 0);
ALTER TABLE "OrderItem" ADD CONSTRAINT "OrderItem_warrantyDaysSnapshot_nonnegative" CHECK ("warrantyDaysSnapshot" IS NULL OR "warrantyDaysSnapshot" >= 0);

CREATE TABLE "RefundRequest" (
  "id" UUID NOT NULL DEFAULT gen_random_uuid(), "orderId" UUID NOT NULL, "customerProfileId" UUID NOT NULL,
  "status" "RefundRequestStatus" NOT NULL DEFAULT 'REQUESTED', "reasonCode" VARCHAR(80) NOT NULL, "reasonText" VARCHAR(1000),
  "requestedAmount" DECIMAL(18,2), "approvedAmount" DECIMAL(18,2), "reviewedAt" TIMESTAMP(3), "reviewedByUserId" UUID,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "RefundRequest_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "RefundRequest_amounts_positive" CHECK (("requestedAmount" IS NULL OR "requestedAmount" > 0) AND ("approvedAmount" IS NULL OR "approvedAmount" > 0))
);
CREATE TABLE "RefundRequestItem" (
  "id" UUID NOT NULL DEFAULT gen_random_uuid(), "refundRequestId" UUID NOT NULL, "orderItemId" UUID NOT NULL, "quantity" INTEGER NOT NULL, "calculatedAmount" DECIMAL(18,2) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "RefundRequestItem_pkey" PRIMARY KEY ("id"), CONSTRAINT "RefundRequestItem_quantity_positive" CHECK ("quantity" > 0), CONSTRAINT "RefundRequestItem_amount_positive" CHECK ("calculatedAmount" > 0)
);
CREATE TABLE "Refund" (
  "id" UUID NOT NULL DEFAULT gen_random_uuid(), "refundRequestId" UUID NOT NULL, "paymentId" UUID NOT NULL, "provider" "PaymentProvider" NOT NULL DEFAULT 'PAYSTACK',
  "providerReference" VARCHAR(120) NOT NULL, "providerRefundId" VARCHAR(160), "status" "RefundStatus" NOT NULL DEFAULT 'CREATED', "amount" DECIMAL(18,2) NOT NULL, "currencyCode" VARCHAR(3) NOT NULL,
  "requestedAt" TIMESTAMP(3), "succeededAt" TIMESTAMP(3), "failedAt" TIMESTAMP(3), "failureCode" VARCHAR(160), "failureMessage" VARCHAR(1000), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "Refund_pkey" PRIMARY KEY ("id"), CONSTRAINT "Refund_amount_positive" CHECK ("amount" > 0), CONSTRAINT "Refund_currencyCode_uppercase" CHECK ("currencyCode" ~ '^[A-Z]{3}$')
);
CREATE TABLE "RefundEvent" (
  "id" UUID NOT NULL DEFAULT gen_random_uuid(), "refundId" UUID NOT NULL, "providerStatus" VARCHAR(80) NOT NULL, "providerRefundId" VARCHAR(160), "amountMinor" DECIMAL(30,0), "currencyCode" VARCHAR(3), "evidence" JSONB NOT NULL, "observedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "RefundEvent_pkey" PRIMARY KEY ("id"), CONSTRAINT "RefundEvent_currencyCode_uppercase" CHECK ("currencyCode" IS NULL OR "currencyCode" ~ '^[A-Z]{3}$')
);
CREATE UNIQUE INDEX "Refund_refundRequestId_key" ON "Refund"("refundRequestId"); CREATE UNIQUE INDEX "Refund_providerReference_key" ON "Refund"("providerReference"); CREATE UNIQUE INDEX "Refund_providerRefundId_key" ON "Refund"("providerRefundId"); CREATE INDEX "Refund_status_updatedAt_idx" ON "Refund"("status", "updatedAt"); CREATE UNIQUE INDEX "RefundRequestItem_refundRequestId_orderItemId_key" ON "RefundRequestItem"("refundRequestId", "orderItemId"); CREATE INDEX "RefundRequestItem_orderItemId_idx" ON "RefundRequestItem"("orderItemId"); CREATE INDEX "RefundRequest_orderId_createdAt_idx" ON "RefundRequest"("orderId", "createdAt"); CREATE INDEX "RefundRequest_status_createdAt_idx" ON "RefundRequest"("status", "createdAt"); CREATE INDEX "RefundEvent_refundId_observedAt_idx" ON "RefundEvent"("refundId", "observedAt");
ALTER TABLE "RefundRequest" ADD CONSTRAINT "RefundRequest_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "RefundRequest" ADD CONSTRAINT "RefundRequest_customerProfileId_fkey" FOREIGN KEY ("customerProfileId") REFERENCES "CustomerProfile"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "RefundRequest" ADD CONSTRAINT "RefundRequest_reviewedByUserId_fkey" FOREIGN KEY ("reviewedByUserId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "RefundRequestItem" ADD CONSTRAINT "RefundRequestItem_refundRequestId_fkey" FOREIGN KEY ("refundRequestId") REFERENCES "RefundRequest"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "RefundRequestItem" ADD CONSTRAINT "RefundRequestItem_orderItemId_fkey" FOREIGN KEY ("orderItemId") REFERENCES "OrderItem"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Refund" ADD CONSTRAINT "Refund_refundRequestId_fkey" FOREIGN KEY ("refundRequestId") REFERENCES "RefundRequest"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Refund" ADD CONSTRAINT "Refund_paymentId_fkey" FOREIGN KEY ("paymentId") REFERENCES "Payment"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "RefundEvent" ADD CONSTRAINT "RefundEvent_refundId_fkey" FOREIGN KEY ("refundId") REFERENCES "Refund"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

CREATE TABLE "ReturnRequest" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "orderId" UUID NOT NULL, "customerProfileId" UUID NOT NULL, "status" "ReturnRequestStatus" NOT NULL DEFAULT 'REQUESTED', "reasonCode" "ReturnReasonCode" NOT NULL, "reasonText" VARCHAR(1000), "approvedAt" TIMESTAMP(3), "receivedAt" TIMESTAMP(3), "completedAt" TIMESTAMP(3), "resolutionRefundRequestId" UUID, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ReturnRequest_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ReturnItem" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "returnRequestId" UUID NOT NULL, "orderItemId" UUID NOT NULL, "quantity" INTEGER NOT NULL, "condition" VARCHAR(160), "inspectionNote" VARCHAR(1000), "resolution" "ReturnResolution", "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ReturnItem_pkey" PRIMARY KEY ("id"), CONSTRAINT "ReturnItem_quantity_positive" CHECK ("quantity" > 0));
CREATE TABLE "ReturnStatusHistory" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "returnRequestId" UUID NOT NULL, "previousStatus" "ReturnRequestStatus", "newStatus" "ReturnRequestStatus" NOT NULL, "actorUserId" UUID, "reason" VARCHAR(1000), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ReturnStatusHistory_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "ReturnRequest_resolutionRefundRequestId_key" ON "ReturnRequest"("resolutionRefundRequestId"); CREATE INDEX "ReturnRequest_orderId_createdAt_idx" ON "ReturnRequest"("orderId", "createdAt"); CREATE INDEX "ReturnRequest_status_createdAt_idx" ON "ReturnRequest"("status", "createdAt"); CREATE UNIQUE INDEX "ReturnItem_returnRequestId_orderItemId_key" ON "ReturnItem"("returnRequestId", "orderItemId"); CREATE INDEX "ReturnItem_orderItemId_idx" ON "ReturnItem"("orderItemId"); CREATE INDEX "ReturnStatusHistory_returnRequestId_createdAt_idx" ON "ReturnStatusHistory"("returnRequestId", "createdAt");
ALTER TABLE "ReturnRequest" ADD CONSTRAINT "ReturnRequest_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "ReturnRequest" ADD CONSTRAINT "ReturnRequest_customerProfileId_fkey" FOREIGN KEY ("customerProfileId") REFERENCES "CustomerProfile"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "ReturnItem" ADD CONSTRAINT "ReturnItem_returnRequestId_fkey" FOREIGN KEY ("returnRequestId") REFERENCES "ReturnRequest"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "ReturnItem" ADD CONSTRAINT "ReturnItem_orderItemId_fkey" FOREIGN KEY ("orderItemId") REFERENCES "OrderItem"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "ReturnStatusHistory" ADD CONSTRAINT "ReturnStatusHistory_returnRequestId_fkey" FOREIGN KEY ("returnRequestId") REFERENCES "ReturnRequest"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "ReturnStatusHistory" ADD CONSTRAINT "ReturnStatusHistory_actorUserId_fkey" FOREIGN KEY ("actorUserId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

CREATE TABLE "WarrantyClaim" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "customerProfileId" UUID NOT NULL, "orderItemId" UUID NOT NULL, "status" "WarrantyClaimStatus" NOT NULL DEFAULT 'SUBMITTED', "issueDescription" VARCHAR(2000) NOT NULL, "submittedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "reviewedAt" TIMESTAMP(3), "reviewedByUserId" UUID, "resolution" "WarrantyResolution", "resolutionNote" VARCHAR(1000), "resolutionRefundRequestId" UUID, "completedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "WarrantyClaim_pkey" PRIMARY KEY ("id"));
CREATE TABLE "WarrantyStatusHistory" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "warrantyClaimId" UUID NOT NULL, "previousStatus" "WarrantyClaimStatus", "newStatus" "WarrantyClaimStatus" NOT NULL, "actorUserId" UUID, "reason" VARCHAR(1000), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "WarrantyStatusHistory_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "WarrantyClaim_resolutionRefundRequestId_key" ON "WarrantyClaim"("resolutionRefundRequestId"); CREATE INDEX "WarrantyClaim_orderItemId_createdAt_idx" ON "WarrantyClaim"("orderItemId", "createdAt"); CREATE INDEX "WarrantyClaim_status_createdAt_idx" ON "WarrantyClaim"("status", "createdAt"); CREATE INDEX "WarrantyStatusHistory_warrantyClaimId_createdAt_idx" ON "WarrantyStatusHistory"("warrantyClaimId", "createdAt");
ALTER TABLE "WarrantyClaim" ADD CONSTRAINT "WarrantyClaim_customerProfileId_fkey" FOREIGN KEY ("customerProfileId") REFERENCES "CustomerProfile"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "WarrantyClaim" ADD CONSTRAINT "WarrantyClaim_orderItemId_fkey" FOREIGN KEY ("orderItemId") REFERENCES "OrderItem"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "WarrantyClaim" ADD CONSTRAINT "WarrantyClaim_reviewedByUserId_fkey" FOREIGN KEY ("reviewedByUserId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "WarrantyStatusHistory" ADD CONSTRAINT "WarrantyStatusHistory_warrantyClaimId_fkey" FOREIGN KEY ("warrantyClaimId") REFERENCES "WarrantyClaim"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "WarrantyStatusHistory" ADD CONSTRAINT "WarrantyStatusHistory_actorUserId_fkey" FOREIGN KEY ("actorUserId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

CREATE TABLE "SupplierCommissionRate" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "supplierId" UUID NOT NULL, "rate" DECIMAL(8,6) NOT NULL, "effectiveFrom" TIMESTAMP(3) NOT NULL, "effectiveTo" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "SupplierCommissionRate_pkey" PRIMARY KEY ("id"), CONSTRAINT "SupplierCommissionRate_rate_range" CHECK ("rate" >= 0 AND "rate" <= 1), CONSTRAINT "SupplierCommissionRate_period_valid" CHECK ("effectiveTo" IS NULL OR "effectiveTo" > "effectiveFrom"));
CREATE TABLE "CommissionRecord" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "orderItemId" UUID NOT NULL, "supplierId" UUID NOT NULL, "supplierOrderId" UUID NOT NULL, "grossAmount" DECIMAL(18,2) NOT NULL, "commissionRate" DECIMAL(8,6) NOT NULL, "commissionAmount" DECIMAL(18,2) NOT NULL, "supplierNetAmount" DECIMAL(18,2) NOT NULL, "currencyCode" VARCHAR(3) NOT NULL, "status" "CommissionRecordStatus" NOT NULL DEFAULT 'EARNED', "earnedAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "CommissionRecord_pkey" PRIMARY KEY ("id"), CONSTRAINT "CommissionRecord_rate_range" CHECK ("commissionRate" >= 0 AND "commissionRate" <= 1), CONSTRAINT "CommissionRecord_money_valid" CHECK ("grossAmount" >= 0 AND "commissionAmount" >= 0 AND "supplierNetAmount" >= 0 AND "grossAmount" = "commissionAmount" + "supplierNetAmount"), CONSTRAINT "CommissionRecord_currency_uppercase" CHECK ("currencyCode" ~ '^[A-Z]{3}$'));
CREATE TABLE "SupplierLedgerEntry" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "supplierId" UUID NOT NULL, "currencyCode" VARCHAR(3) NOT NULL, "type" "SupplierLedgerEntryType" NOT NULL, "amountSigned" DECIMAL(18,2) NOT NULL, "referenceType" VARCHAR(80) NOT NULL, "referenceId" VARCHAR(160) NOT NULL, "description" VARCHAR(1000), "actorUserId" UUID, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "SupplierLedgerEntry_pkey" PRIMARY KEY ("id"), CONSTRAINT "SupplierLedgerEntry_amount_nonzero" CHECK ("amountSigned" <> 0), CONSTRAINT "SupplierLedgerEntry_currency_uppercase" CHECK ("currencyCode" ~ '^[A-Z]{3}$'));
CREATE TABLE "SupplierSettlement" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "supplierId" UUID NOT NULL, "currencyCode" VARCHAR(3) NOT NULL, "periodStart" TIMESTAMP(3), "periodEnd" TIMESTAMP(3), "status" "SupplierSettlementStatus" NOT NULL DEFAULT 'DRAFT', "grossEarnings" DECIMAL(18,2) NOT NULL, "refundAdjustments" DECIMAL(18,2) NOT NULL, "otherAdjustments" DECIMAL(18,2) NOT NULL, "netAmount" DECIMAL(18,2) NOT NULL, "createdByUserId" UUID NOT NULL, "approvedAt" TIMESTAMP(3), "approvedByUserId" UUID, "markedPaidAt" TIMESTAMP(3), "markedPaidByUserId" UUID, "externalReference" VARCHAR(200), "note" VARCHAR(1000), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SupplierSettlement_pkey" PRIMARY KEY ("id"), CONSTRAINT "SupplierSettlement_currency_uppercase" CHECK ("currencyCode" ~ '^[A-Z]{3}$'), CONSTRAINT "SupplierSettlement_period_valid" CHECK ("periodEnd" IS NULL OR "periodStart" IS NULL OR "periodEnd" > "periodStart"));
CREATE TABLE "SupplierSettlementItem" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "settlementId" UUID NOT NULL, "ledgerEntryId" UUID NOT NULL, "amount" DECIMAL(18,2) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "SupplierSettlementItem_pkey" PRIMARY KEY ("id"), CONSTRAINT "SupplierSettlementItem_amount_nonzero" CHECK ("amount" <> 0));
CREATE UNIQUE INDEX "SupplierCommissionRate_supplierId_effectiveFrom_key" ON "SupplierCommissionRate"("supplierId", "effectiveFrom"); CREATE INDEX "SupplierCommissionRate_supplierId_effectiveFrom_idx" ON "SupplierCommissionRate"("supplierId", "effectiveFrom"); CREATE UNIQUE INDEX "CommissionRecord_orderItemId_key" ON "CommissionRecord"("orderItemId"); CREATE INDEX "CommissionRecord_supplierId_earnedAt_idx" ON "CommissionRecord"("supplierId", "earnedAt"); CREATE UNIQUE INDEX "SupplierLedgerEntry_type_referenceId_key" ON "SupplierLedgerEntry"("type", "referenceId"); CREATE INDEX "SupplierLedgerEntry_supplierId_currencyCode_createdAt_idx" ON "SupplierLedgerEntry"("supplierId", "currencyCode", "createdAt"); CREATE INDEX "SupplierSettlement_supplierId_currencyCode_status_createdAt_idx" ON "SupplierSettlement"("supplierId", "currencyCode", "status", "createdAt"); CREATE UNIQUE INDEX "SupplierSettlementItem_ledgerEntryId_key" ON "SupplierSettlementItem"("ledgerEntryId"); CREATE INDEX "SupplierSettlementItem_settlementId_idx" ON "SupplierSettlementItem"("settlementId");
ALTER TABLE "SupplierCommissionRate" ADD CONSTRAINT "SupplierCommissionRate_supplierId_fkey" FOREIGN KEY ("supplierId") REFERENCES "Supplier"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "CommissionRecord" ADD CONSTRAINT "CommissionRecord_orderItemId_fkey" FOREIGN KEY ("orderItemId") REFERENCES "OrderItem"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "CommissionRecord" ADD CONSTRAINT "CommissionRecord_supplierId_fkey" FOREIGN KEY ("supplierId") REFERENCES "Supplier"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "CommissionRecord" ADD CONSTRAINT "CommissionRecord_supplierOrderId_fkey" FOREIGN KEY ("supplierOrderId") REFERENCES "SupplierOrder"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "SupplierLedgerEntry" ADD CONSTRAINT "SupplierLedgerEntry_supplierId_fkey" FOREIGN KEY ("supplierId") REFERENCES "Supplier"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "SupplierLedgerEntry" ADD CONSTRAINT "SupplierLedgerEntry_actorUserId_fkey" FOREIGN KEY ("actorUserId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "SupplierSettlement" ADD CONSTRAINT "SupplierSettlement_supplierId_fkey" FOREIGN KEY ("supplierId") REFERENCES "Supplier"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "SupplierSettlement" ADD CONSTRAINT "SupplierSettlement_createdByUserId_fkey" FOREIGN KEY ("createdByUserId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "SupplierSettlement" ADD CONSTRAINT "SupplierSettlement_approvedByUserId_fkey" FOREIGN KEY ("approvedByUserId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "SupplierSettlement" ADD CONSTRAINT "SupplierSettlement_markedPaidByUserId_fkey" FOREIGN KEY ("markedPaidByUserId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "SupplierSettlementItem" ADD CONSTRAINT "SupplierSettlementItem_settlementId_fkey" FOREIGN KEY ("settlementId") REFERENCES "SupplierSettlement"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "SupplierSettlementItem" ADD CONSTRAINT "SupplierSettlementItem_ledgerEntryId_fkey" FOREIGN KEY ("ledgerEntryId") REFERENCES "SupplierLedgerEntry"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
